mapper.select:
select d.dish_id, d.dept_id, d.name, d.cover, d.description, d.tags, d.duration, d.level, d.serve, d.kcal, d.ingredients, d.steps, d.tips, d.status, d.sort, d.source, d.del_flag, d.create_by, d.create_time, d.update_by, d.update_time, d.remark, (select c.name from meal_category_ref r join meal_category c on c.category_id = r.category_id and c.del_flag = '0' where r.biz_type = 1 and r.biz_id = d.dish_id limit 1) as category_names, t.cnt as order_count from ( select i.dish_id as dish_id, sum(i.count) as cnt from meal_order_item i inner join meal_order o on o.order_id = i.order_id where o.del_flag = '0' and o.status = '2' and o.create_time >= concat(#{startDay}, ' 00:00:00') and o.create_time <= concat(#{endDay}, ' 23:59:59') and i.dish_id is not null
and o.dept_id = #{deptId}
group by i.dish_id ) t inner join meal_dish d on d.dish_id = t.dish_id where d.del_flag = '0' and d.status = '0' order by t.cnt desc, d.sort asc, d.dish_id asc limit #{limit}
